// ================================================================
// CHECK BREACHED SLAs
// Query sla_tracking for entries that have breached threshold
// but haven't been escalated yet.
// ================================================================
const supabaseUrl = $env?.AISHA_POSTGREST_URL || '';
const serviceKey = $env?.AISHA_POSTGREST_SERVICE_KEY || '';

const SLA_BREACH_MS = 30 * 60 * 1000; // 30 minutes
const cutoff = new Date(Date.now() - SLA_BREACH_MS).toISOString();

try {
  const res = await fetch(
    `${supabaseUrl}/rest/v1/sla_tracking?first_response_at=is.null&sla_breached=eq.false&first_message_at=lt.${encodeURIComponent(cutoff)}&select=id,story_id,matrix_room_id,first_message_at`,
    {
      headers: {
        'apikey': serviceKey,
        'Authorization': `Bearer ${serviceKey}`,
      },
    }
  );

  const breached = await res.json();

  if (!Array.isArray(breached) || breached.length === 0) {
    return { json: { action: 'no_breaches', count: 0 } };
  }

  return breached.map(item => ({
    json: {
      action: 'escalate',
      slaId: item.id,
      storyId: item.story_id,
      matrixRoomId: item.matrix_room_id,
      firstMessageAt: item.first_message_at,
      waitingMinutes: Math.round((Date.now() - new Date(item.first_message_at).getTime()) / 60000),
    },
  }));
} catch (err) {
  return { json: { action: 'error', error: err.message } };
}

// ================================================================
// ESCALATE — Mark SLA as breached and send notification
// ================================================================
const supabaseUrl = $env?.AISHA_POSTGREST_URL || '';
const serviceKey = $env?.AISHA_POSTGREST_SERVICE_KEY || '';
const synapseUrl = $env?.SYNAPSE_ADMIN_URL || 'http://synapse:8008';
const aishaToken = $env?.AISHA_MATRIX_ACCESS_TOKEN || '';

const slaId = $json.slaId;
const storyId = $json.storyId;
const roomId = $json.matrixRoomId;
const waitingMinutes = $json.waitingMinutes;

try {
  // 1. Mark SLA as breached
  await fetch(
    `${supabaseUrl}/rest/v1/sla_tracking?id=eq.${slaId}`,
    {
      method: 'PATCH',
      headers: {
        'Content-Type': 'application/json',
        'apikey': serviceKey,
        'Authorization': `Bearer ${serviceKey}`,
        'Prefer': 'return=minimal',
      },
      body: JSON.stringify({
        sla_breached: true,
        escalated_at: new Date().toISOString(),
      }),
    }
  );

  // 2. Send AISHA escalation message to Matrix room
  if (roomId && aishaToken) {
    const txnId = 'm.sla.' + Date.now() + '.' + Math.random().toString(36).slice(2, 8);
    const escalationMsg = `⚠️ **SLA Breach Alert**\n\nThis conversation has been waiting for a response for **${waitingMinutes} minutes** (SLA threshold: 30 min).\n\nAuto-escalating to the next available guild expert. Please respond as soon as possible.`;

    await fetch(
      `${synapseUrl}/_matrix/client/v3/rooms/${encodeURIComponent(roomId)}/send/m.room.message/${txnId}`,
      {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${aishaToken}`,
        },
        body: JSON.stringify({
          msgtype: 'm.text',
          body: escalationMsg,
          format: 'org.matrix.custom.html',
          formatted_body: escalationMsg.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>').replace(/\n/g, '<br/>'),
        }),
      }
    );
  }

  // 3. Log to audit_journal
  await fetch(
    `${supabaseUrl}/rest/v1/audit_journal`,
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'apikey': serviceKey,
        'Authorization': `Bearer ${serviceKey}`,
        'Prefer': 'return=minimal',
      },
      body: JSON.stringify({
        action: 'aisha.sla_breach_escalation',
        entity_type: 'sla_tracking',
        entity_id: slaId,
        metadata: {
          story_id: storyId,
          waiting_minutes: waitingMinutes,
          room_id: roomId,
        },
      }),
    }
  );

  return { json: { success: true, slaId, waitingMinutes, escalated: true } };
} catch (err) {
  return { json: { success: false, error: err.message, slaId } };
}
